mapper.select:
select from reading_plan_item i join reading_plan p on p.id = i.plan_id join member m on m.id = p.member_id join book b on b.id = i.book_id
and i.plan_id = #{planId} and p.member_id = #{scopeMemberId} and p.member_id = #{q.memberId}
and (m.name like concat('%', #{q.memberKeyword}, '%') or m.phone like concat('%', #{q.memberKeyword}, '%') or m.email like concat('%', #{q.memberKeyword}, '%'))
and i.book_id = #{q.bookId}
and (b.title like concat('%', #{q.bookKeyword}, '%') or b.author like concat('%', #{q.bookKeyword}, '%') or b.isbn like concat('%', #{q.bookKeyword}, '%'))
and i.status = #{q.status} and i.source = #{q.source}
order by
i.priority i.created_at
p.member_id, i.sequence_no
desc asc

mapper.update:
update reading_plan_item
set sequence_no = #{sequenceNo}, version = version + 1, updated_at = now()
where id = #{id}
